  "personas": [
    {"role":"center_admin","person":"alvarez.marisol","story":"Marisol Alvarez looks after the whole organization: its settings, people, roles and connections to other services."},
    {"role":"executive_committee","person":"nakamura.hana","story":"Hana Nakamura sits on the executive committee: edits people-level information, approves memberships and reads the reports."},
    {"role":"executive_viewer","person":"alvarez.tomas","story":"Tomas Alvarez is a board member who can look at the dashboards and reports but cannot change anything."},
    {"role":"treasurer","person":"brightwater.dana","story":"Dana Brightwater keeps the books: records and refunds gifts, matches the bank, sends statements and closes each month."},
    {"role":"finance_volunteer","person":"brightwater.colin","story":"Colin Brightwater helps the treasurer by recording gifts received offline and matching bank lines, but cannot refund."},
    {"role":"membership_coordinator","person":"okonkwo.ngozi","story":"Ngozi Okonkwo looks after families and memberships: checks new families, approves applications and keeps their numbers straight."},
    {"role":"communications_officer","person":"lindqvist.sofia","story":"Sofia Lindqvist sends announcements and newsletters, answers the shared inboxes and looks after the message templates."},
    {"role":"content_editor","person":"lindqvist.erik","story":"Erik Lindqvist writes the guide and pages and adds photos; what they write waits for someone to approve it."},
    {"role":"privacy_officer","person":"haddad.layla","story":"Layla Haddad handles requests to export or delete someone's information and can read the audit log."},
    {"role":"volunteer_coordinator","person":"haddad.omar","story":"Omar Haddad organizes volunteer groups, shifts, waivers and background checks."},
    {"role":"event_lead","person":"petrov.irina","story":"Irina Petrov runs one event: the attendee list, lunch, volunteers and the checklist for the day.","scope":"ev:cleanup"},
    {"role":"checkin_volunteer","person":"petrov.nikolai","story":"Nikolai Petrov scans tickets at the door on the day of an event and sees no giving information.","scope":"ev:cleanup"},
    {"role":"kitchen_lead","person":"nakamura.ken","story":"Ken Nakamura sees the headcounts and the store's prep lists so the kitchen knows how much to make."},
    {"role":"store_lead","person":"whitfield.grace","story":"Grace Whitfield runs the store: the menu, pickup times, orders and stock."},
    {"role":"store_pickup","person":"whitfield.henry","story":"Henry Whitfield hands out store orders at pickup and marks them picked up."},
    {"role":"zone_lead","person":"moreau.camille","story":"Camille Moreau looks after one zone: its inbox, the contact details of its families and its reports.","scope":"zone:north"},
    {"role":"community_member","person":"reyes.mateo","story":"Mateo Reyes has an account but is not a member yet, and can still RSVP, give, shop and learn."},
    {"role":"membership_reference","person":"okonkwo.emeka","story":"Emeka Okonkwo is a member who vouches for newcomers and approves or declines the applications that name them."},
    {"role":"primary_adult","person":"osei.kwame","story":"Kwame Osei is the main adult of a family: manages the household, the children's profiles, payments and RSVPs."},
    {"role":"adult_member","person":"moreau.jules","story":"Jules Moreau is another adult in a family, with their own profile, the family's pledges, RSVPs and payments."},
    {"role":"child","person":"osei.kofi","story":"Kofi Osei is a child in the family who can see events and learning but cannot RSVP, pledge or pay."}
